'use client'; import { QrCode } from 'lucide-react';
import { useState } from 'react'; import { VendorFeedbackBanner, useVendorFeedback } from '@/components/vendor/ui/useVendorFeedback';
import { VendorModuleHeader, VendorStatusPill } from '@/components/vendor/ui/VendorModuleHeader';
import { vendorFieldClass, vendorLabelClass, VendorModal } from '@/components/vendor/ui/VendorModal';
import { MOCK_WAREHOUSES } from '@/lib/vendor/mock/data'; export function WarehouseWorkspace() { const { feedback, showSuccess } = useVendorFeedback(); const [scannerOpen, setScannerOpen] = useState(false); const [manualSku, setManualSku] = useState(''); const [lastScan, setLastScan] = useState<string | null>(null); const handleScanSubmit = (e: React.FormEvent) => { e.preventDefault(); const sku = manualSku.trim(); if (!sku) return; setLastScan(sku); showSuccess(`SKU ${sku} captured for stock transfer / dispatch.`); setManualSku(''); setScannerOpen(false); }; return ( <div className="space-y-6"> <VendorModuleHeader title="Warehouse Management" description="Storage grid, capacity, barcode dispatch, audit log." /> <VendorFeedbackBanner feedback={feedback} /> <div className="grid grid-cols-1 gap-4 md:grid-cols-3"> {MOCK_WAREHOUSES.map((w) => ( <div key={w.id} className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-4 border-vendor-accent/20 bg-vendor-card"> <p className="font-mono text-xs font-bold text-vendor-secondary ">{w.code}</p> <p className="mt-1 text-sm font-black">{w.name}</p> <div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100 bg-vendor-cream"> <div className="h-full bg-vendor-primary" style={{ width: `${w.capacityPct}%` }} /> </div> <VendorStatusPill label={w.temperatureControlled ? 'Cold chain' : 'Ambient'} tone={w.temperatureControlled ? 'info' : 'neutral'} /> </div> ))} </div> <div className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-6 text-center border-vendor-accent/20 bg-vendor-card"> <QrCode className="mx-auto h-12 w-12 text-slate-400" aria-hidden /> <p className="mt-2 text-sm font-bold">Barcode / QR scanner</p> <p className="text-xs text-vendor-muted">Stock transfer · goods dispatch · audit capture</p> {lastScan ? <p className="mt-2 text-xs font-bold text-vendor-secondary">Last capture: {lastScan}</p> : null} <button type="button" onClick={() => setScannerOpen(true)} className="mt-3 rounded-lg bg-vendor-secondary px-4 py-2 text-xs font-bold text-white " > Open scanner UI </button> </div> <VendorModal title="Scanner · manual SKU entry" open={scannerOpen} onClose={() => setScannerOpen(false)} footer={ <> <button type="button" onClick={() => setScannerOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Close </button> <button type="submit" form="scanner-form" className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white"> Confirm scan </button> </> } > <div className="mb-4 flex h-40 items-center justify-center rounded-xl border border-dashed border-vendor-accent/40 bg-slate-950 text-vendor-primary"> <p className="text-xs font-bold">Camera preview (simulated) · aim barcode at frame</p> </div> <form id="scanner-form" onSubmit={handleScanSubmit} className="space-y-2"> <label className={vendorLabelClass}> Or enter SKU / barcode manually <input autoFocus value={manualSku} onChange={(e) => setManualSku(e.target.value)} placeholder="SKU-000123" className={vendorFieldClass} /> </label> </form> </VendorModal> </div> );
}
